#!/usr/bin/env node
/* Stamp the generated Capacitor Android project with the app version.
 *
 * The `android/` folder is generated by `npx cap add android` (and git-ignored),
 * so version bumps have to be applied after generation. versionName comes from
 * package.json; versionCode comes from the CI run number so every upload to the
 * Play Store is a higher build than the last one.
 *
 *   node scripts/android-version.mjs            # uses GITHUB_RUN_NUMBER
 *   ANDROID_VERSION_CODE=42 node scripts/android-version.mjs
 */
import fs from 'node:fs';

const FILE = 'android/app/build.gradle';

if (!fs.existsSync(FILE)) {
  console.error(`${FILE} not found — run "npx cap add android" first.`);
  process.exit(1);
}

const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const versionName = String(pkg.version || '1.0').replace(/"/g, '');
const rawCode = process.env.ANDROID_VERSION_CODE || process.env.GITHUB_RUN_NUMBER || '1';
const versionCode = Math.min(2100000000, Math.max(1, Math.floor(Number(rawCode) || 1)));

let src = fs.readFileSync(FILE, 'utf8');
const before = src;

src = src.replace(/versionCode\s+\d+/, `versionCode ${versionCode}`);
src = src.replace(/versionName\s+"[^"]*"/, `versionName "${versionName}"`);

if (src === before) {
  console.error('Could not find versionCode/versionName in android/app/build.gradle.');
  process.exit(1);
}

fs.writeFileSync(FILE, src);
console.log(`Android version set to ${versionName} (versionCode ${versionCode}).`);
